using Casbin;

namespace SonrisaNews.Infrastructure.Auth;

/// <summary>
/// Thin wrapper over <see cref="IEnforcer"/> role-grouping calls. Exists for
/// two reasons:
/// <list type="number">
///   <item>
///     Casbin.NET 2.19's grouping API is un-domain-based
///     (<c>AddRoleForUser(user, role)</c>), but <c>RoleGroupingService</c>
///     is shaped to call domain-aware methods so it can be extended
///     later. The wrapper bridges the two: the domain parameter is
///     accepted for forward compatibility but is currently ignored
///     (Casbin.NET 2.19 stores a single global grouping).
///   </item>
///   <item>
///     Tests can substitute a fake <see cref="IEnforcer"/> without
///     depending on Casbin's internal model, by stubbing the four methods
///     here. This keeps the test surface narrow.
///   </item>
/// </list>
/// </summary>
public static class RbacEnforcerExtension
{
    /// <summary>Returns the roles the enforcer has assigned to the user.</summary>
    public static IReadOnlyList<string> GetRolesForUser(IEnforcer enforcer, string userEmail, string domain = "")
        => enforcer.GetRolesForUser(userEmail);

    /// <summary>Adds a single <c>g, user, role</c> grouping.</summary>
    public static Task AddRoleForUserAsync(IEnforcer enforcer, string userEmail, string role, string domain = "")
    {
        enforcer.AddRoleForUser(userEmail, role);
        return Task.CompletedTask;
    }

    /// <summary>Removes a single <c>g, user, role</c> grouping.</summary>
    public static Task DeleteRoleForUserAsync(IEnforcer enforcer, string userEmail, string role, string domain = "")
    {
        enforcer.DeleteRoleForUser(userEmail, role);
        return Task.CompletedTask;
    }

    /// <summary>Removes every <c>g, user, *</c> grouping for the user.</summary>
    public static Task DeleteRolesForUserAsync(IEnforcer enforcer, string userEmail, string domain = "")
    {
        enforcer.DeleteRolesForUser(userEmail);
        return Task.CompletedTask;
    }
}

