using FluentAssertions;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging.Abstractions;
using SonrisaNews.Api.Auth;
using SonrisaNews.Domain;
using SonrisaNews.Domain.Entities;
using SonrisaNews.Infrastructure.Persistence;
using Xunit;

namespace SonrisaNews.UnitTests.Auth;

/// <summary>
/// Tests for <see cref="AdminSeeder"/>. The seeder runs on every startup;
/// it is idempotent (skips if the user exists), fails fast on missing
/// config, and sets <c>MustChangePassword = true</c> so the first sign-in
/// forces a rotation.
/// </summary>
[Trait("Category", AuthTestCategory.Seeder)]
public class AdminSeederTests
{
    [Fact]
    public async Task StartAsync_NoExistingUser_CreatesAnAdmin()
    {
        var db = NewDbContext();
        var options = Options(new AdminSeederOptions
        {
            Email = "admin@sonrisa.local",
            Password = "REPLACE_ME",
            DisplayName = "Bootstrap",
        });

        var seeder = new AdminSeeder(NewScopeFactory(db), options, NullLogger<AdminSeeder>.Instance);

        await seeder.StartAsync(CancellationToken.None);

        var user = await db.Users.SingleAsync();
        user.Email.Should().Be("admin@sonrisa.local");
        user.DisplayName.Should().Be("Bootstrap");
        user.Role.Should().Be(UserRole.Admin);
        user.Status.Should().Be(UserStatus.Active);
        user.MustChangePassword.Should().BeTrue();
        BCrypt.Net.BCrypt.Verify("REPLACE_ME", user.PasswordHash).Should().BeTrue();
    }

    [Fact]
    public async Task StartAsync_ExistingUser_DoesNotRecreate()
    {
        // Idempotency: a second startup with the same config must not
        // re-insert the admin and must not bump MustChangePassword.
        var db = NewDbContext();
        db.Users.Add(new User
        {
            Id = Guid.NewGuid(),
            Email = "admin@sonrisa.local",
            PasswordHash = BCrypt.Net.BCrypt.HashPassword("already-set"),
            DisplayName = "Already Admin",
            Role = UserRole.Admin,
            Status = UserStatus.Active,
            MustChangePassword = false,
        });
        await db.SaveChangesAsync();

        var options = Options(new AdminSeederOptions
        {
            Email = "admin@sonrisa.local",
            Password = "REPLACE_ME",
            DisplayName = "Bootstrap",
        });
        var seeder = new AdminSeeder(NewScopeFactory(db), options, NullLogger<AdminSeeder>.Instance);

        await seeder.StartAsync(CancellationToken.None);

        var users = await db.Users.ToListAsync();
        users.Should().HaveCount(1, "the seeder must not create a duplicate admin");
        users[0].DisplayName.Should().Be("Already Admin", "the existing row is not modified");
    }

    [Fact]
    public async Task StartAsync_MissingEmail_Throws()
    {
        var db = NewDbContext();
        var options = Options(new AdminSeederOptions
        {
            Email = string.Empty,
            Password = "REPLACE_ME",
        });
        var seeder = new AdminSeeder(NewScopeFactory(db), options, NullLogger<AdminSeeder>.Instance);

        var act = () => seeder.StartAsync(CancellationToken.None);

        await act.Should().ThrowAsync<InvalidOperationException>(
            "the seeder must fail fast at startup if the email is missing — " +
            "the operator forgot to set SEED_ADMIN_EMAIL");
    }

    [Fact]
    public async Task StartAsync_MissingPassword_Throws()
    {
        var db = NewDbContext();
        var options = Options(new AdminSeederOptions
        {
            Email = "admin@sonrisa.local",
            Password = string.Empty,
        });
        var seeder = new AdminSeeder(NewScopeFactory(db), options, NullLogger<AdminSeeder>.Instance);

        var act = () => seeder.StartAsync(CancellationToken.None);

        await act.Should().ThrowAsync<InvalidOperationException>(
            "the seeder must fail fast at startup if the password is missing");
    }

    // -- helpers ------------------------------------------------------------

    private static SonrisaNewsDbContext NewDbContext()
    {
        var options = new DbContextOptionsBuilder<SonrisaNewsDbContext>()
            .UseSqlite("Data Source=:memory:")
            .Options;
        var ctx = new SonrisaNewsDbContext(options);
        ctx.Database.OpenConnection();
        ctx.Database.EnsureCreated();
        return ctx;
    }

    private static IServiceScopeFactory NewScopeFactory(SonrisaNewsDbContext ctx)
    {
        var services = new ServiceCollection();
        services.AddLogging();
        services.AddSingleton(ctx);
        var sp = services.BuildServiceProvider();
        return sp.GetRequiredService<IServiceScopeFactory>();
    }

    private static Microsoft.Extensions.Options.IOptions<AdminSeederOptions> Options(AdminSeederOptions o) =>
        Microsoft.Extensions.Options.Options.Create(o);
}

/// <summary>
/// True if the user must rotate their password on the next sign-in.
/// Set by <c>AdminSeeder</c> for the bootstrap admin (the env-var
/// password must be replaced before the account is usable long-term)
/// and by the <c>ForgotPassword</c> flow.
/// </summary>
public bool MustChangePassword { get; set; }

using System.Threading;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using SonrisaNews.Domain;
using SonrisaNews.Domain.Entities;
using SonrisaNews.Infrastructure.Auth;
using SonrisaNews.Infrastructure.Persistence;

namespace SonrisaNews.Api.Auth;

/// <summary>
/// Configuration for the bootstrap admin seeder. Bound from the
/// <c>AdminSeed</c> section of <c>appsettings.json</c> (populated from
/// <c>SEED_ADMIN_EMAIL</c> / <c>SEED_ADMIN_PASSWORD</c> env vars via the
/// API's <c>Program.cs</c>).
/// </summary>
public sealed class AdminSeederOptions
{
    public const string SectionName = "AdminSeed";

    public string Email { get; set; } = string.Empty;
    public string Password { get; set; } = string.Empty;
    public string DisplayName { get; set; } = "Admin";
}

/// <summary>
/// Seeds the first admin user from environment variables. Idempotent:
/// if the user already exists, the seeder is a no-op. The seeder is
/// registered as an <see cref="IHostedService"/> so it runs on every
/// startup, after the migration step has brought the schema up to date.
/// </summary>
/// <remarks>
/// MVP convention per the <c>seed-admin-user</c> skill:
/// <list type="bullet">
///   <item><c>SEED_ADMIN_EMAIL</c> and <c>SEED_ADMIN_PASSWORD</c> are required when the seed runs.</item>
///   <item>The seed is a hard fail at startup if either env var is missing — operators should know about an unset seed, not silently get a no-admin situation.</item>
///   <item>The seeded user gets <c>MustChangePassword = true</c> so the env-var password cannot become the long-term-admin password by accident.</item>
/// </list>
/// </remarks>
public sealed class AdminSeeder(
    IServiceScopeFactory scopeFactory,
    IOptions<AdminSeederOptions> options,
    ILogger<AdminSeeder> logger) : IHostedService
{
    public async Task StartAsync(CancellationToken ct)
    {
        var opts = options.Value;
        if (string.IsNullOrWhiteSpace(opts.Email) || string.IsNullOrWhiteSpace(opts.Password))
        {
            throw new InvalidOperationException(
                "AdminSeeder requires SEED_ADMIN_EMAIL and SEED_ADMIN_PASSWORD. " +
                "Set them via appsettings.json (AdminSeed:Email / AdminSeed:Password), " +
                "user-secrets, or environment variables.");
        }

        await using var scope = await scopeFactory.CreateAsyncScope();
        var db = scope.ServiceProvider.GetRequiredService<SonrisaNewsDbContext>();
        var passwordHasher = scope.ServiceProvider.GetRequiredService<IPasswordHasher>();
        var roleGrouping = scope.ServiceProvider.GetRequiredService<IRoleGroupingService>();

        var normalized = opts.Email.Trim().ToLowerInvariant();
        var existing = await db.Users.FirstOrDefaultAsync(u => u.Email == normalized, ct);
        if (existing is not null)
        {
            logger.LogInformation("Bootstrap admin {Email} already exists; skipping seed.", normalized);
            // Even when the user exists, ensure the Casbin grouping is in
            // place — this catches the case where the in-memory enforcer
            // was reset (e.g. dev restart with a fresh process) but the
            // DB row persists.
            await roleGrouping.EnsureGroupingAsync(existing.Email, existing.Role, ct);
            return;
        }

        var user = new User
        {
            Id = Guid.NewGuid(),
            Email = normalized,
            PasswordHash = passwordHasher.Hash(opts.Password),
            DisplayName = string.IsNullOrWhiteSpace(opts.DisplayName) ? "Admin" : opts.DisplayName.Trim(),
            Role = UserRole.Admin,
            Status = UserStatus.Active,
            TimeZone = "UTC",
            CreatedAt = DateTimeOffset.UtcNow,
            MustChangePassword = true,
        };

        db.Users.Add(user);
        await db.SaveChangesAsync(ct);
        await roleGrouping.EnsureGroupingAsync(user.Email, user.Role, ct);

        logger.LogWarning(
            "Bootstrap admin {Email} created with role Admin. " +
            "The seeded password is from SEED_ADMIN_PASSWORD; rotate it on first sign-in.",
            normalized);
    }

    public Task StopAsync(CancellationToken cancellationToken) => Task.CompletedTask;
}

