{"content":"using Casbin;
using FluentAssertions;
using Microsoft.AspNetCore.Authorization;
using Microsoft.Extensions.Logging.Abstractions;
using NSubstitute;
using SonrisaNews.Domain;
using SonrisaNews.Domain.Auth;
using SonrisaNews.Domain.Entities;
using SonrisaNews.Infrastructure.Auth;
using Xunit;

namespace SonrisaNews.UnitTests.Auth;

/// <summary>
/// Tests for <see cref="RbacPolicyHandler"/>. The handler is the only
/// authorization enforcement point — controllers do not re-check ownership.
/// These tests pin the positive and negative behaviour so a future
/// refactor cannot silently open a permission.
/// </summary>
/// <remarks>
/// The handler reads <see cref="IEnforcerBootstrap"/>. Tests substitute a
/// fake bootstrap that returns a hand-rolled <see cref="IEnforcer"/> built
/// from the same model + CSV the real app uses. That's hermetic (no file
/// I/O, no live Casbin state) and exercises the same code path as
/// production.
/// </remarks>
[Trait("Category", AuthTestCategory.Rbac)]
public class RbacPolicyHandlerTests
{
    [Fact]
    public async Task HandleRequirementAsync_AuthorizedUser_GrantsTheRequirement()
    {
        // The Casbin CSV grants `p, User, Alerts.Read.Own, access`. The fake
        // user is grouped as `g, ada@example.com, User`. Enforce returns true,
        // and the handler calls context.Succeed(requirement).
        var enforcer = TestEnforcer.Create();
        await RbacEnforcerExtension.AddRoleForUserAsync(enforcer, "ada@example.com", Roles.User);

        var currentUser = Substitute.For<ICurrentUser>();
        currentUser.Id.Returns(Guid.NewGuid());
        currentUser.Email.Returns("ada@example.com");
        currentUser.Role.Returns(UserRole.User);

        var bootstrap = Substitute.For<IEnforcerBootstrap>();
        bootstrap.GetEnforcerAsync(Arg.Any<string?>()).Returns(enforcer);

        var handler = new RbacPolicyHandler(currentUser, bootstrap, NullLogger<RbacPolicyHandler>.Instance);

        var context = NewAuthorizationContext();
        var requirement = new PermissionRequirement(Permissions.AlertsReadOwn);

        await handler.HandleAsync(context);

        context.HasSucceeded.Should().BeTrue(
            "the User role is granted Alerts.Read.Own in rbac_policy.csv, so the handler must succeed");
    }

    [Fact]
    public async Task HandleRequirementAsync_UnauthorizedUser_DeniesTheRequirement()
    {
        // Same fixture, but the user is grouped as a freshly invented role
        // that has no policy grant. Enforce returns false and the handler
        // must not call context.Succeed.
        var enforcer = TestEnforcer.Create();
        await RbacEnforcerExtension.AddRoleForUserAsync(enforcer, "ada@example.com", "Ghost");

        var currentUser = Substitute.For<ICurrentUser>();
        currentUser.Id.Returns(Guid.NewGuid());
        currentUser.Email.Returns("ada@example.com");
        currentUser.Role.Returns(UserRole.User);

        var bootstrap = Substitute.For<IEnforcerBootstrap>();
        bootstrap.GetEnforcerAsync(Arg.Any<string?>()).Returns(enforcer);

        var handler = new RbacPolicyHandler(currentUser, bootstrap, NullLogger<RbacPolicyHandler>.Instance);

        var context = NewAuthorizationContext();
        var requirement = new PermissionRequirement(Permissions.AlertsReadOwn);

        await handler.HandleAsync(context);

        context.HasSucceeded.Should().BeFalse(
            "the Ghost role has no policy grant, so the handler must not succeed — even though the user is 'authenticated'");
    }

    [Fact]
    public async Task HandleRequirementAsync_NoCurrentUser_DeniesTheRequirement()
    {
        // Unauthenticated requests should never reach the handler (the
        // JwtBearer middleware returns 401 first), but if the handler is
        // invoked without a current user it must fail closed, not crash.
        var enforcer = TestEnforcer.Create();
        var currentUser = Substitute.For<ICurrentUser>();
        currentUser.Id.Returns((Guid?)null);

        var bootstrap = Substitute.For<IEnforcerBootstrap>();
        bootstrap.GetEnforcerAsync(Arg.Any<string?>()).Returns(enforcer);

        var handler = new RbacPolicyHandler(currentUser, bootstrap, NullLogger<RbacPolicyHandler>.Instance);

        var context = NewAuthorizationContext();

        await handler.HandleAsync(context);

        context.HasSucceeded.Should().BeFalse("the handler must fail closed when no current user is bound");
        await bootstrap.DidNotReceive().GetEnforcerAsync(Arg.Any<string?>());
    }

    private static AuthorizationHandlerContext NewAuthorizationContext() =>
        new(
            new[] { new PermissionRequirement(Permissions.AlertsReadOwn) },
            new System.Security.Claims.ClaimsPrincipal(),
            resource: null);
}

/// <summary>Category constants for the auth-test suite. Pinning the strings in one place catches typos at compile time.</summary>
internal static class AuthTestCategory
{
    public const string Rbac = "Auth.Rbac";
    public const string Signup = "Auth.Signup";
    public const string Seeder = "Auth.Seeder";
}

/// <summary>
/// Builds a real <see cref="IEnforcer"/> from the project-shipped model +
/// policy files. Used by the handler tests so we exercise the same code
/// path the production app uses — but loaded once per test to keep tests
/// independent.
/// </summary>
internal static class TestEnforcer
{
    public static IEnforcer Create()
    {
        // The model and CSV are copied to the test bin folder via the
        // <None Include="Auth\..." CopyToOutputDirectory="PreserveNewest" />
        // items in SonrisaNews.Infrastructure.csproj. Test bin → test
        // assembly's directory.
        var assemblyDir = AppContext.BaseDirectory;
        var modelPath = Path.Combine(assemblyDir, "Auth", "casbin_model.conf");
        var policyPath = Path.Combine(assemblyDir, "Auth", "rbac_policy.csv");

        // Fall back to walking up the directory tree to the source tree if
        // the test bin doesn't carry the files (e.g. when the test
        // assembly is loaded from a different location).
        if (!File.Exists(modelPath))
        {
            modelPath = LocateFromRepoRoot("backend/src/SonrisaNews.Infrastructure/Auth/casbin_model.conf");
            policyPath = LocateFromRepoRoot("backend/src/SonrisaNews.Infrastructure/Auth/rbac_policy.csv");
        }

        return new Enforcer(modelPath, policyPath);
    }

    private static string LocateFromRepoRoot(string relative)
    {
        var root = SonrisaNews.Shared.SonrisaRepositoryPaths.FindRepoRoot(AppContext.BaseDirectory)
            ?? throw new InvalidOperationException(
                "Could not find the Sonrisa News repo root from " + AppContext.BaseDirectory);
        return Path.Combine(root, relative.Replace('/', Path.DirectorySeparatorChar));
    }
}
