using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using SonrisaNews.Domain;
using SonrisaNews.Domain.Entities;
using SonrisaNews.Infrastructure.Persistence;

namespace SonrisaNews.Api.Auth;

/// <summary>
/// Configuration for <see cref="AdminSeeder"/>. Bound from the
/// <c>AdminSeed</c> section in <c>appsettings.json</c>; in production the
/// values come from env vars (<c>AdminSeed__Email</c>,
/// <c>AdminSeed__Password</c>, <c>AdminSeed__DisplayName</c>).
/// </summary>
public sealed class AdminSeederOptions
{
    public const string SectionName = "AdminSeed";

    /// <summary>Email of the bootstrap admin. Required.</summary>
    public string Email { get; set; } = string.Empty;

    /// <summary>Initial password. The user is required to change it on first sign-in.</summary>
    public string Password { get; set; } = string.Empty;

    /// <summary>Display name. Defaults to <c>"Admin"</c>.</summary>
    public string DisplayName { get; set; } = "Admin";
}

/// <summary>
/// Idempotently seeds the bootstrap admin on every API startup. If the
/// user already exists, the seeder is a no-op. If <c>Email</c> or
/// <c>Password</c> is missing, the seeder throws — fail fast at startup
/// rather than on the first admin endpoint call.
/// </summary>
/// <remarks>
/// <para>
/// The seeder is the only place that turns an env-var password into a
/// <c>PasswordHash</c>. <see cref="BCryptPasswordHasher"/> is intentionally
/// not reused here so a future swap to Argon2id doesn't silently change
/// the bootstrap admin's hash algorithm. The work factor is documented
/// inline.
/// </para>
/// <para>
/// <see cref="MustChangePassword"/> is set to <c>true</c> on the bootstrap
/// admin so the operator's env-var password cannot become the
/// long-term-admin password by accident.
/// </para>
/// </remarks>
public sealed class AdminSeeder(
    IServiceScopeFactory scopeFactory,
    IOptions<AdminSeederOptions> options,
    ILogger<AdminSeeder> logger) : IHostedService
{
    /// <summary>BCrypt work factor. Matches <see cref="BCryptPasswordHasher"/>.</summary>
    private const int WorkFactor = 12;

    public async Task StartAsync(CancellationToken ct)
    {
        var opts = options.Value;
        if (string.IsNullOrWhiteSpace(opts.Email))
        {
            logger.LogError("AdminSeeder: AdminSeed:Email is empty. Set SEED_ADMIN_EMAIL / AdminSeed__Email.");
            throw new InvalidOperationException(
                "AdminSeed:Email is required. Set SEED_ADMIN_EMAIL or AdminSeed__Email in the environment.");
        }
        if (string.IsNullOrWhiteSpace(opts.Password))
        {
            logger.LogError("AdminSeeder: AdminSeed:Password is empty. Set SEED_ADMIN_PASSWORD / AdminSeed__Password.");
            throw new InvalidOperationException(
                "AdminSeed:Password is required. Set SEED_ADMIN_PASSWORD or AdminSeed__Password in the environment.");
        }

        await using var scope = scopeFactory.CreateAsyncScope();
        var db = scope.ServiceProvider.GetRequiredService<SonrisaNewsDbContext>();

        var existing = await db.Users.FirstOrDefaultAsync(u => u.Email == opts.Email, ct);
        if (existing is not null)
        {
            logger.LogInformation("Bootstrap admin {Email} already exists; skipping seed.", opts.Email);
            return;
        }

        var passwordHash = BCrypt.Net.BCrypt.HashPassword(opts.Password, WorkFactor);

        db.Users.Add(new User
        {
            Id = Guid.NewGuid(),
            Email = opts.Email,
            PasswordHash = passwordHash,
            DisplayName = string.IsNullOrWhiteSpace(opts.DisplayName) ? "Admin" : opts.DisplayName,
            Role = UserRole.Admin,
            Status = UserStatus.Active,
            TimeZone = "UTC",
            CreatedAt = DateTimeOffset.UtcNow,
            MustChangePassword = true,
        });

        await db.SaveChangesAsync(ct);
        logger.LogWarning(
            "Bootstrap admin {Email} created. The user MUST change their password on first sign-in.",
            opts.Email);
    }

    public Task StopAsync(CancellationToken ct) => Task.CompletedTask;
}
