const DEFAULT_API_URL = "http://localhost:5080";

/**
 * Resolves the API base URL. Returns the supplied value when set and
 * non-empty; otherwise the dev default. Exposed as a pure function so
 * tests can pin both branches without touching `process.env`.
 */
export const getApiUrl = (rawValue: string | undefined): string => {
  if (rawValue === undefined || rawValue.length === 0) return DEFAULT_API_URL;
  return rawValue;
};

/**
 * The frozen env object consumed by the rest of the app. Reads
 * `NEXT_PUBLIC_API_URL` at module load; the value is then immutable.
 */
export const env = {
  apiUrl: getApiUrl(process.env.NEXT_PUBLIC_API_URL)

import { describe, expect, it } from "vitest";

import { getApiUrl } from "@/lib/env";

describe("getApiUrl", () => {
  it("returns the dev default when the env var is undefined", () => {
    expect(getApiUrl(undefined)).toBe("http://localhost:5080");
  });

  it("returns the dev default when the env var is the empty string", () => {
    // An empty `NEXT_PUBLIC_API_URL` is operationally a misconfig, but
    // the function must still fall back to a usable URL rather than
    // passing "" down to openapi-fetch.
    expect(getApiUrl("")).toBe("http://localhost:5080");
  });

  it("returns the supplied value when set and non-empty", () => {
    expect(getApiUrl("https://api.example.com")).toBe("https://api.example.com");
  });
});

