      } catch {
        // The interceptor logs and re-throws; we treat a refresh
        // failure as "signed out" and let the user re-authenticate.
      } finally {
        if (!cancelled) {
          setState((prev) => ({ ...prev, isInitializing: false }));
        }
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const setSession = useCallback((response: SignInResponse) => {
    setSessionInternal(setState, response);
  }, []);

  const clearSession = useCallback(() => {
    setState((prev) => ({
      ...prev,
      userId: null,
      email: null,
      accessToken: null,
      permissions: [],
    }));
  }, []);

  const loadPermissions = useCallback(async () => {
    const { data, response } = await apiClient.GET("/api/v1/me/permissions", {});
    if (!response.ok || !data) return;
    setState((prev) => ({ ...prev, permissions: data.Permissions }));
  }, []);

  const value = useMemo<AuthContextValue>(
    () => ({
      ...state,
      isAuthenticated: state.accessToken !== null,
      hasPermission: (p) => state.permissions.includes(p),
      setSession,
      clearSession,
      loadPermissions,
    }),
    [state, setSession, clearSession, loadPermissions],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

/** Hook. Throws if used outside the provider — that's a misuse, not a runtime concern. */
export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext);
  if (ctx === null) {
    throw new Error("useAuth must be used inside <AuthProvider>");
  }
  return ctx;
}

function setSessionInternal(
  setState: React.Dispatch<React.SetStateAction<AuthState>>,
  response: SignInResponse,
): void {
  setState((prev) => ({
    ...prev,
    userId: response.UserId,
    email: response.Email,
    accessToken: response.AccessToken,
    permissions: [], // Reset permissions; the next loadPermissions() repopulates.
  }));
