/**
 * Auth store. A tiny, framework-agnostic state container (no Zustand
 * or React) so the OpenAPI client middleware can read the access
 * token on every request without depending on a React hook. The
 * <c>AuthProvider</c> is a thin React wrapper that subscribes to this
 * store via <c>useSyncExternalStore</c>.
 *
 * Trade-off: a hard refresh logs the user out. The handoff defers a
 * short-lived server-readable cookie to wave 11+ — for wave 3 the
 * in-memory token is the smallest correct surface. On app mount the
 * <c>AuthProvider</c> calls <c>POST /api/v1/auth/refresh</c> (the
 * cookie is sent automatically); if the refresh fails, the user
 * lands on the sign-in page.
 */

import type { SignInResponse } from "@/lib/api/schema";

export type AuthStoreState = {
  userId: string | null;
  email: string | null;
  /** The access token, or `null` if signed out. In-memory only. */
  accessToken: string | null;
  /** Granted permission names. Empty until `loadPermissions` has been called. */
  permissions: ReadonlyArray<string>;
  /** True until the provider has finished its initial mount-time refresh probe. */
  isInitializing: boolean;
};

type Listener = () => void;

const initialState: AuthStoreState = {
  userId: null,
  email: null,
  accessToken: null,
  permissions: [],
  isInitializing: true,
};

let state: AuthStoreState = initialState;
const listeners = new Set<Listener>();

function emit(): void {
  for (const l of listeners) l();
}

export const useAuthStore = {
  /** Subscribe to state changes. The returned function unsubscribes. */
  subscribe(listener: Listener): () => void {
    listeners.add(listener);
    return () => listeners.delete(listener);
  },
  /** Snapshot the current state. Stable reference; React `useSyncExternalStore` requires this. */
  getState(): AuthStoreState {
    return state;
  },
  /** Persists the access token + identity after a sign-in / sign-up. */
  setSession(response: SignInResponse): void {
    state = {
      ...state,
      userId: response.UserId,
      email: response.Email,
      accessToken: response.AccessToken,
      permissions: [],
    };
    emit();
  },
  /** Updates only the access token. Used by the refresh-on-401 middleware. */
  setAccessToken(token: string): void {
    state = { ...state, accessToken: token };
    emit();
  },
  /** Updates the granted permission set. */
  setPermissions(permissions: ReadonlyArray<string>): void {
    state = { ...state, permissions };
    emit();
  },
  /** Forgets the access token + identity. Called on sign-out and on refresh-failed. */
  clearSession(): void {
    state = {
      ...state,
      userId: null,
      email: null,
      accessToken: null,
      permissions: [],
    };
    emit();
  },
  /** Marks the provider's initial mount-time refresh probe as complete. */
  finishInitializing(): void {
    if (!state.isInitializing) return;
    state = { ...state, isInitializing: false };
    emit();
  },
};

provider. A thin React wrapper around the framework-agnostic
 * <c>authStore</c> (see ./authStore). The store is the source of
 * truth so the OpenAPI client middleware (which runs outside React)
 * can read the access token on every request.
 *
 * On mount the provider kicks off a single refresh probe so a
 * returning user (with a still-valid httpOnly cookie) lands on the
 * dashboard without a sign-in. If the refresh fails, the user stays
 * signed out and the sign-in page handles the redirect.
 *
 * Trade-off: a hard refresh logs the user out unless the refresh
 * probe succeeds. The handoff defers a short-lived server-readable
 * cookie to wave 11+ — for wave 3 the in-memory token + mount-time
 * refresh is the smallest correct surface.
 */
"use client";

import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useSyncExternalStore,
  type ReactNode,
} from "react";

import { apiClient } from "@/lib/api/client";
import { useAuthStore, type AuthStoreState } from "@/lib/auth/authStore";

export type AuthContextValue = {
  isAuthenticated: boolean;
  hasPermission: (permission: string) => boolean;
  /** Same shape as the store; exposed as a single object for ergonomic consumption. */
  state: AuthStoreState;
};

const AuthContext = createContext<AuthContextValue | null>(null);

export function AuthProvider({ children }: { children: ReactNode }): React.JSX.Element {
  const state = useSyncExternalStore(
    useAuthStore.subscribe,
    useAuthStore.getState,
    useAuthStore.getState,
  );

  // Mount-time refresh probe. Runs once per app load; the `useEffect`
  // cleanup flag prevents a state update after unmount (which would
  // warn in React strict mode dev).
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const { data, response } = await apiClient.POST("/api/v1/auth/refresh", {});
        if (cancelled) return;
        if (response.ok && data) {
          useAuthStore.setSession(data);
        }
      } catch {
        // The refresh failed (no cookie, expired cookie, etc.). The
        // user is signed out — the sign-in page handles it.
      } finally {
        if (!cancelled) {
          useAuthStore.finishInitializing();
        }
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const value = useMemo<AuthContextValue>(
    () => ({
