{"content":"/**
 * Auth client. Holds the in-memory access token (never persisted to
 * localStorage / sessionStorage per the
 * <c>nextjs-react.instructions.md</c> rule) and exposes the
 * <c>useAuth()</c> hook. The refresh token is an httpOnly cookie
 * managed by the API; the client never reads it.
 *
 * Trade-off: a hard refresh logs the user out. The handoff defers a
 * short-lived server-readable cookie to wave 11+ — for wave 3 the
 * in-memory token is the smallest correct surface. The
 * <c>AuthProvider</c> re-hydrates the access token on app mount by
 * calling <c>POST /api/v1/auth/refresh</c> (the cookie is sent
 * automatically); if the refresh fails, the user lands on the
 * sign-in page.
 */
"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";

import { apiClient } from "@/lib/api/client";
import type { SignInResponse } from "@/lib/api/schema";

type AuthState = {
  /** The user's id, or `null` if signed out. */
  userId: string | null;
  /** The user's email, or `null` if signed out. */
  email: string | null;
  /** The access token, or `null` if signed out. In-memory only. */
  accessToken: string | null;
  /** Granted permission names. Empty until `loadPermissions` has been called. */
  permissions: ReadonlyArray<string>;
  /**
   * True until the provider has finished its initial mount-time
   * refresh probe. Pages behind the auth gate should render a
   * skeleton (or `loading.tsx`) while this is true.
   */
  isInitializing: boolean;
};

export type AuthContextValue = AuthState & {
  /** True iff the user has a valid in-memory access token. */
  isAuthenticated: boolean;
  /** True iff the user has the given permission. */
  hasPermission: (permission: string) => boolean;
  /** Persists the access token + identity in memory after a sign-in / sign-up. */
  setSession: (response: SignInResponse) => void;
  /** Forgets the access token + identity. Called on sign-out and on 401-refresh-failed. */
  clearSession: () => void;
  /** Fetches `/api/v1/me/permissions` and caches the result. Idempotent. */
  loadPermissions: () => Promise<void>;
};

const AuthContext = createContext<AuthContextValue | null>(null);

/**
 * Provider. Place once near the root of the React tree (inside
 * <c>AppProviders</c>) so every Server Component / Client Component
 * subtree shares the same in-memory state.
 */
export function AuthProvider({ children }: { children: ReactNode }): React.JSX.Element {
  const [state, setState] = useState<AuthState>({
    userId: null,
    email: null,
    accessToken: null,
    permissions: [],
    isInitializing: true,
  });

  // On mount, try to refresh the access token via the httpOnly
  // cookie. If the cookie is missing or stale, the refresh fails and
  // the user lands on the sign-in page (no state change).
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const { data, response } = await apiClient.POST("/api/v1/auth/refresh", {});
        if (cancelled) return;
        if (response.ok && data) {
          setSessionInternal(setState, data);
        }
      } catch {
        // The interceptor logs and re-throws; we treat a refresh
        // failure as "signed out" and let the user re-authenticate.
      } finally {
        if (!cancelled) {
          setState((prev) => ({ ...prev, isInitializing: false }));
        }
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const setSession = useCallback((response: SignInResponse) => {
    setSessionInternal(setState, response);
  }, []);

  const clearSession = useCallback(() => {
    setState((prev) => ({
      ...prev,
      userId: null,
      email: null,
      accessToken: null,
      permissions: [],
    }));
  }, []);

  const loadPermissions = useCallback(async () => {
    const { data, response } = await apiClient.GET("/api/v1/me/permissions", {});
    if (!response.ok || !data) return;
    setState((prev) => ({ ...prev, permissions: data.Permissions }));
  }, []);

  const value = useMemo<AuthContextValue>(
    () => ({
      ...state,
      isAuthenticated: state.accessToken !== null,
      hasPermission: (p) => state.permissions.includes(p),
      setSession,
      clearSession,
      loadPermissions,
    }),
    [state, setSession, clearSession, loadPermissions],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

/** Hook. Throws if used outside the provider — that's a misuse, not a runtime concern. */
export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext);
  if (ctx === null) {
    throw new Error("useAuth must be used inside <AuthProvider>");
  }
  return ctx;
}

function setSessionInternal(
  setState: React.Dispatch<React.SetStateAction<AuthState>>,
  response: SignInResponse,
): void {
  setState((prev) => ({
    ...prev,
    userId: response.UserId,
    email: response.Email,
    accessToken: response.AccessToken,
    permissions: [], // Reset permissions; the next loadPermissions() repopulates.
  }));
}
