  isInitializing: boolean;
};

export type AuthContextValue = AuthState & {
  /** True iff the user has a valid in-memory access token. */
  isAuthenticated: boolean;
  /** True iff the user has the given permission. */
  hasPermission: (permission: string) => boolean;
  /** Persists the access token + identity in memory after a sign-in / sign-up. */
  setSession: (response: SignInResponse) => void;
  /** Forgets the access token + identity. Called on sign-out and on 401-refresh-failed. */
  clearSession: () => void;
  /** Fetches `/api/v1/me/permissions` and caches the result. Idempotent. */
  loadPermissions: () => Promise<void>;
};

const AuthContext = createContext<AuthContextValue | null>(null);

/**
 * Provider. Place once near the root of the React tree (inside
 * <c>AppProviders</c>) so every Server Component / Client Component
 * subtree shares the same in-memory state.
 */
export function AuthProvider({ children }: { children: ReactNode }): React.JSX.Element {
  const [state, setState] = useState<AuthState>({
    userId: null,
    email: null,
    accessToken: null,
    permissions: [],
    isInitializing: true,
  });

  // On mount, try to refresh the access token via the httpOnly
  // cookie. If the cookie is missing or stale, the refresh fails and
  // the user lands on the sign-in page (no state change).
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const { data, response } = await apiClient.POST("/api/v1/auth/refresh", {});
        if (cancelled) return;
        if (response.ok && data) {
