{"content":"#!/usr/bin/env node
/**
 * OpenAPI drift check. CI calls `pnpm generate:api:check`; the
 * script regenerates the schema into a temp file and `diff`s it
 * against the committed one. Exit 0 = no drift, exit 1 = drift.
 *
 * The script does NOT call out to the network. CI is expected to
 * have a live API at `http://localhost:5080` (e.g. via the
 * `dev: up` task) before this runs. If the API is down, the
 * underlying `openapi-typescript` call fails and the script exits 2.
 */
import { execSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const COMMITTED = "lib/api/schema.ts";
const API_URL = process.env.OPENAPI_URL ?? "http://localhost:5080/openapi/v1.json";

const tmp = mkdtempSync(join(tmpdir(), "sonrisa-openapi-"));
const regenPath = join(tmp, "schema.ts");

try {
  execSync(
    `pnpm exec openapi-typescript ${API_URL} -o ${regenPath}`,
    { stdio: "inherit" },
  );
  const committed = readFileSync(COMMITTED, "utf8");
  const regen = readFileSync(regenPath, "utf8");
  if (committed === regen) {
    console.log("✔  lib/api/schema.ts matches the live OpenAPI doc.");
    process.exit(0);
  }
  console.error("❌ lib/api/schema.ts is out of date with the live OpenAPI doc.");
  console.error("   Run `pnpm generate:api` and commit the new schema.ts.");
  process.exit(1);
} catch (err) {
  console.error("❌ OpenAPI drift check failed to run.");
  console.error(err);
  process.exit(2);
} finally {
  rmSync(tmp, { recursive: true, force: true });
}
