  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const { data, response } = await apiClient.POST("/api/v1/auth/refresh");
        if (cancelled) return;
        if (response.ok && data) {
          useAuthStore.getState().setSession(data);
        }
      } catch {
        // The refresh failed (no cookie, expired cookie, etc.). The
        // user is signed out — the sign-in page handles it.
      } finally {
        if (!cancelled) {
          useAuthStore.getState().finishInitializing();
        }
      }
    })();
    return () => {
